  const calendarGrouped = useMemo(
    () =>
      CALENDAR_DELTAS.map((r) => ({
        name: r.short,
        Aug: r.augPct,
        Q3: r.q3Pct,
        fill: r.fill,
      })),
    [],
  );

  const stockBars = useMemo(
    () =>
      STOCK_INDEX_LENSES.map((s) => ({
        name: s.short,
        sharePct: s.sharePct,
        fill: s.fill,
        label: s.label,
      })),
