/**
 * QA: ai-financing-concentration-2026q3
 * // viz-types: Lorenz area+line, vintage grouped bars, dual-line supply path, stack donut, channel bars, stock-index bars, lens scatter | layout: default
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  AI_DEBT_STACK,
  ETF_FLOW_SHARES,
  HEADLINE,
  ISSUER_SHARES,
  VINTAGE_COMPARE,
} from "../src/data/ai-financing-concentration-2026q3-data.ts";

assert.equal(HEADLINE.top1IssuerSharePct, 41);
assert.equal(HEADLINE.top3IssuerSharePct, 76);
assert.equal(HEADLINE.hsShareOfAiDebtPct, 40);
assert.equal(HEADLINE.aiIgSupplySharePct, 23);
assert.equal(HEADLINE.aiIgSupplyShareAugPct, 18);
assert.equal(HEADLINE.aiIgDeltaPp, 5);
assert.equal(HEADLINE.aiTaggedIgStockPct, 15);
assert.equal(ISSUER_SHARES[0].short, "AMZN");
assert.equal(ISSUER_SHARES[0].sharePct, 41);
assert.equal(AI_DEBT_STACK[0].sharePct, 40);
assert.equal(ETF_FLOW_SHARES[0].ticker, "QQQ");
assert.ok(VINTAGE_COMPARE.some((r) => r.moved && r.q3Pct === 23));

const root = process.cwd();
const slug = "ai-financing-concentration-2026q3";
const markers = [
  "AI financing ??? Q3 concentration lens",
  "Sticky vs moved: Aug ??? Q3 concentration meters",
  "Hyperscaler IG issuer ladder",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(150);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4184);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(
      '[data-viz="ai-financing-concentration-2026q3"]',
      { timeout: 20000 },
    );
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "Issuer ladder");
    await clickBtn(page, "Calendar + stock");
    await clickBtn(page, "Show HY");
    await clickBtn(page, "Channels + ETF");
    await clickBtn(page, "$ billions");
    await clickBtn(page, "Aug ??? Q3 deltas");
    await clickBtn(page, "Moved only");
    await clickBtn(page, "Sticky only");
    console.log("??? auditVizInteractions");
    const audit = await auditVizInteractions(page);
    if (audit.issues.length > 0) {
      console.error("??? Viz interaction audit failed", audit);
      process.exit(1);
    }
    if (audit.warnings?.length) {
      console.log("warnings:", audit.warnings.join(" | "));
    }
    console.log("qa-ai-financing-concentration-2026q3: PASS");
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

